1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.*;
4	import com.loja.checkout.cupom.*;
5	import com.loja.checkout.dto.ItemRequest;
6	import com.loja.checkout.dto.ResumoRequest;
7	import com.loja.checkout.dto.ResumoResponse;
8	import com.loja.checkout.entrega.*;
9	import com.loja.checkout.exception.CheckoutException;
10	import com.loja.checkout.pagamento.*;
11	import org.springframework.stereotype.Service;
12	
13	import java.math.BigDecimal;
14	import java.math.RoundingMode;
15	import java.util.List;
16	import java.util.Map;
17	
18	@Service
19	public class ResumoService {
20	
21	    private final Map<String, ModalidadeEntrega> modalidades = Map.of(
22	            "ECONOMICA", new Economica(),
23	            "EXPRESSA", new Expressa(),
24	            "RETIRADA_LOJA", new RetiradaLoja(),
25	            "MOTOBOY", new Motoboy()
26	    );
27	
28	    private final Map<String, Cupom> cupons = Map.of(
29	            "BEMVINDO10", new BemVindo10(),
30	            "MENOS50", new Menos50(),
31	            "FRETEGRATIS", new FreteGratis(),
32	            "LEVE3PAGUE2", new Leve3Pague2()
33	    );
34	
35	    private final Map<String, NivelClube> niveis = Map.of(
36	            "BRONZE", new Bronze(),
37	            "PRATA", new Prata(),
38	            "OURO", new Ouro()
39	    );
40	
41	    private final Map<String, FormaPagamento> formasPagamento = Map.of(
42	            "PIX", new Pix(),
43	            "CARTAO", new Cartao(),
44	            "BOLETO", new Boleto()
45	    );
46	
47	    private final Map<String, BigDecimal> taxasSeguro = Map.of(
48	            "SUDESTE", new BigDecimal("0.01"),
49	            "SUL", new BigDecimal("0.01"),
50	            "CENTRO_OESTE", new BigDecimal("0.015"),
51	            "NORTE", new BigDecimal("0.025"),
52	            "NORDESTE", new BigDecimal("0.02")
53	    );
54	
55	    public ResumoResponse calcular(ResumoRequest req) {
56	        validarItens(req.itens());
57	
58	        NivelClube nivel = buscar(niveis, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
59	        BigDecimal taxaSeguro = buscarTaxa(req.regiao());
60	        ModalidadeEntrega entrega = buscar(modalidades, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
61	
62	        BigDecimal pesoTotal = calcularPeso(req.itens());
63	        if (!entrega.disponivel(pesoTotal)) {
64	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
65	        }
66	
67	        Cupom cupom = null;
68	        if (req.cupom() != null && !req.cupom().isBlank()) {
69	            cupom = buscar(cupons, req.cupom(), "CUPOM_INVALIDO");
70	        }
71	
72	        FormaPagamento pagamento = buscar(formasPagamento, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
73	        int parcelas = req.parcelas() != null ? req.parcelas() : 1;
74	        if (!pagamento.parcelamentoValido(parcelas)) {
75	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
76	        }
77	
78	        BigDecimal subtotal = calcularSubtotal(req.itens());
79	
80	        if (cupom != null && !cupom.aplicavel(subtotal, req.itens())) {
81	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
82	        }
83	
84	        BigDecimal frete = entrega.calcularFrete(pesoTotal);
85	        if (nivel.freteGratis()) {
86	            frete = BigDecimal.ZERO.setScale(2);
87	        }
88	
89	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
90	        if (cupom != null) {
91	            descontoCupom = cupom.calcularDesconto(subtotal, req.itens(), frete);
92	        }
93	
94	        BigDecimal seguro = subtotal.multiply(taxaSeguro).setScale(2, RoundingMode.HALF_EVEN);
95	
96	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
97	
98	        if (!pagamento.disponivel(totalPedido)) {
99	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
100	        }
101	
102	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
103	
104	        BigDecimal credito = nivel.calcularCredito(subtotal);
105	        boolean brinde = nivel.brinde(subtotal);
106	
107	        return new ResumoResponse(
108	                subtotal,
109	                descontoCupom,
110	                frete,
111	                entrega.prazoDias(),
112	                seguro,
113	                resultado.ajuste(),
114	                resultado.totalFinal(),
115	                parcelas,
116	                resultado.valorParcela(),
117	                credito,
118	                brinde
119	        );
120	    }
121	
122	    private void validarItens(List<ItemRequest> itens) {
123	        if (itens == null || itens.isEmpty()) {
124	            throw new CheckoutException("PEDIDO_INVALIDO");
125	        }
126	        for (ItemRequest item : itens) {
127	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
128	                    || item.quantidade() == null || item.quantidade() <= 0
129	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
130	                throw new CheckoutException("PEDIDO_INVALIDO");
131	            }
132	        }
133	    }
134	
135	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
136	        BigDecimal subtotal = BigDecimal.ZERO;
137	        for (ItemRequest item : itens) {
138	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
139	        }
140	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
141	    }
142	
143	    private BigDecimal calcularPeso(List<ItemRequest> itens) {
144	        BigDecimal peso = BigDecimal.ZERO;
145	        for (ItemRequest item : itens) {
146	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
147	        }
148	        return peso;
149	    }
150	
151	    private BigDecimal buscarTaxa(String regiao) {
152	        if (regiao == null || !taxasSeguro.containsKey(regiao)) {
153	            throw new CheckoutException("REGIAO_INVALIDA");
154	        }
155	        return taxasSeguro.get(regiao);
156	    }
157	
158	    private <T> T buscar(Map<String, T> mapa, String chave, String codigoErro) {
159	        if (chave == null || !mapa.containsKey(chave)) {
160	            throw new CheckoutException(codigoErro);
161	        }
162	        return mapa.get(chave);
163	    }
164	}
