1	package com.loja.checkout.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public class Cartao implements FormaPagamento {
7	
8	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
9	    private static final int MAX_SEM_JUROS = 3;
10	    private static final int MAX_PARCELAS = 12;
11	
12	    @Override
13	    public boolean parcelamentoValido(int parcelas) {
14	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
15	    }
16	
17	    @Override
18	    public boolean disponivel(BigDecimal totalPedido) {
19	        return true;
20	    }
21	
22	    @Override
23	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
24	        if (parcelas <= MAX_SEM_JUROS) {
25	            BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
26	            return new ResultadoPagamento(totalPedido, valorParcela, BigDecimal.ZERO.setScale(2));
27	        }
28	
29	        double taxa = TAXA_MENSAL.doubleValue();
30	        double fator = taxa / (1 - Math.pow(1 + taxa, -parcelas));
31	        BigDecimal valorParcela = totalPedido.multiply(BigDecimal.valueOf(fator)).setScale(2, RoundingMode.HALF_EVEN);
32	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
33	        BigDecimal ajuste = totalFinal.subtract(totalPedido);
34	        return new ResultadoPagamento(totalFinal, valorParcela, ajuste);
35	    }
36	}
